                                  <div className="text-[10px] text-zinc-500">Adjust range to market price</div>
                              </div>
                          </div>
                          <button 
                              onClick={() => setAutoRebalance(!autoRebalance)}
                              className={`w-10 h-5 rounded-full relative transition-colors ${autoRebalance ? 'bg-emerald-500' : 'bg-zinc-700'}`}
                          >
                              <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${autoRebalance ? 'left-6' : 'left-1'}`}></div>
                          </button>
                      </div>

                      {autoRebalance && (
                          <div className="flex items-start gap-2 p-2 bg-amber-500/10 border border-amber-500/20 rounded-lg animate-in fade-in slide-in-from-top-1">
                              <AlertTriangle size={12} className="text-amber-500 mt-0.5" />
                              <p className="text-[9px] text-amber-500/90 leading-tight">
                                  <strong>Warning:</strong> Frequent rebalancing may incur significant gas fees.
                              </p>
                          </div>
                      )}
                  </div>
              </div>

           </div>

        </div>
      </div>
    </div>
  );
};

